package io.knowledgebrain.activity;
import java.net.*;import java.net.http.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import tools.jackson.databind.json.JsonMapper;
final class ActivityClickHouse {
 private final URI origin;private final HttpClient http;private final String user,key;private final JsonMapper json=JsonMapper.builder().build();
 ActivityClickHouse(String origin,String trust,String directory)throws Exception{this.origin=ActivityHttp.origin(origin);http=ActivityHttp.client(trust);user=Files.readString(Path.of(directory,"username")).strip();key=Files.readString(Path.of(directory,"password")).strip();if(!Set.of("activity_reader","activity_projector").contains(user)||!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Scoped ClickHouse credentials required");}
 private byte[] query(String sql,Map<String,String> params){var uri=new StringBuilder("/?wait_end_of_query=1&date_time_input_format=best_effort");params.forEach((k,v)->uri.append("&param_").append(k).append("=").append(URLEncoder.encode(v,StandardCharsets.UTF_8)));var response=ActivityHttp.send(http,HttpRequest.newBuilder(origin.resolve(uri.toString())).timeout(Duration.ofSeconds(7)).header("X-ClickHouse-User",user).header("X-ClickHouse-Key",key).header("Content-Type","text/plain; charset=utf-8").POST(HttpRequest.BodyPublishers.ofString(sql,StandardCharsets.UTF_8)).build(),16777216);if(response.statusCode()!=200)throw new IllegalStateException("ClickHouse query unavailable");return response.body();}
 void health(){query("SELECT 1",Map.of());}
 void apply(ActivityEvent e){applyAll(List.of(e));}
 void applyAll(List<ActivityEvent> entries){if(!user.equals("activity_projector"))throw new IllegalStateException("Projector identity required");if(entries.isEmpty()||entries.size()>100)throw ActivityEvent.invalid();var sql=new StringBuilder("INSERT INTO brain_activity.timeline FORMAT JSONEachRow\n");for(var e:entries)sql.append(json.writeValueAsString(Map.of("event_id",e.eventId().toString(),"space_id",e.spaceId().toString(),"occurred_at",e.occurredAt(),"entry",json.writeValueAsString(e)))).append('\n');query(sql.toString(),Map.of());}
 List<ActivityEvent> list(UUID space,ActivityQuery q){ActivityEvent.id(space.toString());var params=new HashMap<String,String>();params.put("space",space.toString());params.put("from",Long.toString(q.from()));params.put("to",Long.toString(q.to()));String sql="SELECT entry FROM brain_activity.timeline FINAL WHERE space_id={space:UUID} AND toUnixTimestamp64Milli(occurred_at)>={from:Int64} AND toUnixTimestamp64Milli(occurred_at)<{to:Int64}";if(!q.kind().equals("ALL")){sql+=" AND JSONExtractString(entry,'kind')={kind:String}";params.put("kind",q.kind());}if(q.before()!=null){sql+=" AND (toUnixTimestamp64Milli(occurred_at),toString(event_id)) < ({before:Int64},{event:String})";params.put("before",q.before().toString());params.put("event",q.event().toString());}sql+=" ORDER BY occurred_at DESC,toString(event_id) DESC LIMIT "+(q.limit()+1)+" FORMAT JSONEachRow";String body=new String(query(sql,params),StandardCharsets.UTF_8);var result=new ArrayList<ActivityEvent>();for(String line:body.split("\n")){if(line.isBlank())continue;var event=json.readValue(json.readTree(line).path("entry").asString(),ActivityEvent.class);if(!event.spaceId().equals(space)||!ActivityEvent.TOPICS.containsKey(event.kind())||!ActivityEvent.target(event)||event.sourceVersion()<1)throw new IllegalStateException("Invalid activity projection scope");ActivityEvent.id(event.eventId().toString());long time=Instant.parse(event.occurredAt()).toEpochMilli();if(time<q.from()||time>=q.to()||!q.kind().equals("ALL")&&!event.kind().equals(q.kind()))throw new IllegalStateException("Invalid activity projection filter");if(!result.isEmpty()){var prior=result.getLast();int compare=Instant.parse(prior.occurredAt()).compareTo(Instant.parse(event.occurredAt()));if(compare<0||compare==0&&prior.eventId().toString().compareTo(event.eventId().toString())<=0)throw new IllegalStateException("Invalid activity order");}result.add(event);}if(result.size()>q.limit()+1)throw new IllegalStateException("Activity page exceeds limit");return List.copyOf(result);}
}
